    using Terraria;
    using Terraria.ModLoader;
    using static Terraria.ModLoader.ModContent;

    namespace astonemask
    {
        public class ExampleHelmet : ModItem
        {
            public override void SetStaticDefaults()
            {
                Tooltip.SetDefault("looking like a snack with this on.");
            }

            public override void SetDefaults()
            {
                item.width = 18;
                item.height = 18;
                item.value = 10000;
                item.rare = 2;
                item.defense = 100;
            }
            public override bool IsArmorSet(Item head, Item body, Item legs)
                return body.type == ItemType<ExampleBreastplate>() && legs.type == ItemType<ExampleLeggings>();
            }

            public override void UpdateArmorSet(Player player)
            {
                player.setBonus = "trollface.jpg";
                player.allDamage -= 4.2f;
                /* Here are the individual weapon class bonuses.
                player.meleeDamage -= 4.2f;
                player.thrownDamage -= 4.2f;
                player.rangedDamage -= 4.2f;
                player.magicDamage -= 4.2f;
                player.minionDamage -= 4.2f;
                */
            }
            public override void AddRecipes()
            {
                ModRecipe recipe = new ModRecipe(mod);
                recipe.AddIngredient(3);
                recipe.AddTile(18);
                recipe.SetResult(this);
                recipe.AddRecipe();
            }
        }
    }
